const fs = require('fs');
const p = 'src/app/[school_slug]/page.tsx';
let lines = fs.readFileSync(p, 'utf8').split('\n');

// Find the early returns
let schoolNotFoundStart = -1, schoolNotFoundEnd = -1;
let configLoadedStart = -1, configLoadedEnd = -1;

for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes('if (isSchoolNotFound) {') && schoolNotFoundStart === -1) {
    schoolNotFoundStart = i;
    schoolNotFoundEnd = i + 2; // block is 3 lines
  }
  if (lines[i].includes('if (!isConfigLoaded || !isGlobalConfigLoaded) {') && configLoadedStart === -1) {
    configLoadedStart = i - 1; // include the comment above
    configLoadedEnd = i + 6; // block is 7 lines
  }
}

// Extract them
let earlyReturns = lines.slice(schoolNotFoundStart, schoolNotFoundEnd + 1).concat(lines.slice(configLoadedStart, configLoadedEnd + 1));

// Remove them from their original place
lines.splice(configLoadedStart, configLoadedEnd - configLoadedStart + 1);
lines.splice(schoolNotFoundStart, schoolNotFoundEnd - schoolNotFoundStart + 1);

// Add const [isConfigLoaded] at the top of Home (line 184 roughly)
for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes('const params = useParams();')) {
    lines.splice(i, 0, '  const [isConfigLoaded, setIsConfigLoaded] = useState(false);');
    break;
  }
}

// Re-insert early returns right before "return (" of the main JSX
for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes('<div className="relative min-h-screen')) {
    lines.splice(i - 1, 0, ...earlyReturns);
    break;
  }
}

fs.writeFileSync(p, lines.join('\n'));
console.log("Moved early returns and added isConfigLoaded");

