const { createClient } = require('@supabase/supabase-js');
const bcrypt = require('bcryptjs');
require('dotenv').config({ path: '.env.local' });

const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SECRET_KEY;

if (!supabaseUrl || !supabaseKey) {
  console.error('FATAL: SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must be set in .env.local');
  process.exit(1);
}

const DEFAULT_PASSWORD = process.env.SEED_DEFAULT_PASSWORD;
if (!DEFAULT_PASSWORD) {
  console.error('FATAL: SEED_DEFAULT_PASSWORD must be set in .env.local');
  process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseKey);

async function run() {
  const hash = bcrypt.hashSync(DEFAULT_PASSWORD, 10);

  // Update Kevin
  await supabase.from('admin_users').update({ password_hash: hash }).eq('username', 'Kevin');
  console.log(`Kevin password updated to ${DEFAULT_PASSWORD}`);

  // Update admin_tb
  await supabase.from('admin_users').update({ password_hash: hash }).eq('username', 'admin_tb');
  console.log(`admin_tb password updated to ${DEFAULT_PASSWORD}`);
}
run();

const { Pool } = require('pg');
const dotenv = require('dotenv');
dotenv.config({ path: '.env.local' });

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

async function run() {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    
    // Reset sequence using setval
    // setval(sequence_name, val, is_called)
    // If is_called is true, the next nextval() will return val + 1
    // So if we set it to 1 and true, the next ID will be 2.
    await client.query("SELECT setval('prospective_schools_id_seq', 1, true)");
    console.log('Reset sequence prospective_schools_id_seq to 2 using setval.');
    
    await client.query('COMMIT');
    console.log('Success!');
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Error:', err);
  } finally {
    client.release();
    pool.end();
  }
}

run();

