          setFieldsConfig(parsed);
        }
      } catch (_e) {}
    }

    const savedMajors = localStorage.getItem('ppdb_majors_config');
    if (savedMajors) {
      try {
        const parsed = JSON.parse(savedMajors);
        if (Array.isArray(parsed) && parsed.length > 0) {
