                              e.preventDefault(); e.stopPropagation();
                              setDragActiveStates(prev => ({ ...prev, banner: false }));
                              if (e.dataTransfer.files && e.dataTransfer.files[0]) {
                                processMediaFile(e.dataTransfer.files[0], "banner");
