                                <span className="text-[7px] font-bold text-slate-400 uppercase mt-0.5">Atau Klik Explorer</span>
                              </div>
                            </div>
                          )}
                        </div>

                      </div>

                      {/* Right: Core Fields, Careers, Facilities, Gallery */}
                      <div className="lg:col-span-2 space-y-6">
                        
                        {/* 2.4 General Texts */}
