function AppearanceSettingsSection() {
  const { adminToken, addToast, schoolId } = usePPDB();
  const [themeColor, setThemeColor] = useState("#2563EB");
  const [isSaving, setIsSaving] = useState(false);

  const PRESET_COLORS = [
