                  case "h-14": return { width: 105, height: 56 };
                  case "h-12": return { width: 90, height: 48 };
                  case "h-10": return { width: 75, height: 40 };
                  case "h-8": return { width: 60, height: 32 };
                  default: return { width: 120, height: 60 };
                }
              };

              return (
                <div className="w-full">
