                {step >= 3 && (
                  <div className="space-y-6">
                    
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                      <div className="bg-slate-50/80 px-5 py-4 border-b border-slate-200 flex items-center gap-3">
