          </motion.div>

          {/* Komentar Floating */}
          {COMMENTS_DATA.map((comment) => (
            <FloatingComment
              key={comment.id}
              phase={phase}
              name={comment.name}
              text={comment.text}
              avatarUrl={comment.avatarUrl}
              tags={comment.tags}
              x={comment.x}
              y={comment.y}
              delay={comment.delay}
              isBlurred={comment.isBlurred}
              emoji={comment.emoji}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

