              className={`text-6xl md:text-8xl lg:text-[10vw] font-black ${item.color} uppercase tracking-tighter shrink-0 font-heading select-none leading-none`}
            >
              {item.text}
            </h2>
          ))}
        </motion.div>

        {/* LAYER 1: Kartu Testimonial Foreground */}
        <motion.div
          style={{ x: xCards }}
          className="absolute z-10 flex w-max h-full items-start px-[10vw] gap-10 md:gap-16 will-change-transform"
        >
          {testimonials.map((testimonial) => (
            <div
              key={testimonial.id}
              className={`shrink-0 flex items-start ${testimonial.cardStyle}`}
            >
              <div className="w-full bg-white p-7 md:p-9 border border-zinc-200/80 rounded-[2rem] shadow-[0_10px_30px_rgba(0,0,0,0.03)] hover:shadow-[0_20px_40px_rgba(0,0,0,0.08)] hover:border-zinc-300 transition-all duration-500 hover:-translate-y-2 cursor-pointer group flex flex-col justify-between min-h-[310px]">
                <div>
                  <div className="w-10 h-10 rounded-2xl bg-zinc-50 border border-zinc-100 flex items-center justify-center text-zinc-400 group-hover:bg-yellow-400 group-hover:text-zinc-950 group-hover:border-yellow-400 transition-colors duration-300 mb-5">
                    <svg
                      className="w-4 h-4"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path d="M14.017 21v-7.391c0-5.704 3.731-9.57 8.983-10.609l.995 2.151c-2.432.917-3.995 3.638-3.995 5.849h4v10h-9.983zm-14.017 0v-7.391c0-5.704 3.748-9.57 9-10.609l.996 2.151c-2.433.917-3.996 3.638-3.996 5.849h3.983v10h-9.983z" />
                    </svg>
                  </div>

                  <p className="text-zinc-600 text-sm md:text-base leading-relaxed mb-6 font-medium">
                    "{testimonial.text}"
                  </p>
                </div>

                {/* Profil Karakter DiceBear */}
                <div className="flex items-center gap-3.5 mt-auto pt-4 border-t border-zinc-100">
                  <div className="w-11 h-11 rounded-full bg-zinc-100 border border-zinc-200 overflow-hidden shrink-0">
                    <img
                      src={`https://api.dicebear.com/9.x/notionists/svg?seed=${encodeURIComponent(testimonial.name)}&scale=120&backgroundColor=transparent`}
                      alt={testimonial.name}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                      loading="lazy"
                    />
                  </div>
                  <div className="flex flex-col gap-0.5">
                    <h4 className="text-zinc-900 font-bold text-sm leading-tight">
                      {testimonial.name}
                    </h4>
                    <span className="text-xs text-yellow-400 uppercase tracking-wider font-semibold">
                      {testimonial.role}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </motion.div>
      </div>
    </section>
  );
}

export { TestimonialsSection };

